  "It closed before it opened. Try again.": "Il s’est fermé avant de s’ouvrir. Réessaie.",
  "It couldn’t start on this Mac.": "Il n’a pas pu démarrer sur ce Mac.",
  "It ended before it could write up the build.": "Il s’est terminé avant de pouvoir résumer le build.",
  "It finishes its own setup the first time it opens.": "Il termine sa propre configuration à sa première ouverture.",
  "It hasn't started yet.": "Ça n’a pas encore commencé.",
  "It installs when you relaunch; Genex tells you when it's ready.":
    "Elle s’installera au redémarrage ; Genex te préviendra quand elle sera prête.",
  "It is on and stays on: its new code runs as soon as it loads, and each of its tools asks you again before it runs.":
    "Il est activé et le reste : son nouveau code s’exécute dès qu’il est chargé, et chacun de ses outils te redemandera avant de s’exécuter.",
  "It isn’t on this Mac any more. Install it again.": "Il n’est plus sur ce Mac. Réinstalle-le.",
  "It keeps downloading if you go back.": "Le téléchargement continue si tu reviens en arrière.",
  "It keeps your scripts as files in this game's folder and tells Genex which Studio is this game's.":
    "Il garde tes scripts en fichiers dans le dossier de ce jeu et indique à Genex quel Studio est celui de ce jeu.",
  "It kept getting this wrong, so it stopped to save your credits.":
    "Ça ratait à chaque fois, alors tout s’est arrêté pour économiser tes crédits.",
  "It leaves Play and genex.games and goes back to drafts. The direct link still works, and plays and likes stay if it’s published again.":
    "Il quitte « Jouer » et genex.games et retourne dans les brouillons. Le lien direct marche toujours, et les parties et les j’aime restent s’il est republié.",
  "It leaves the game’s Store. Players who own it keep it.": "Il quitte la boutique du jeu. Ceux qui l’ont le gardent.",
  "It may need the setup scripts its packages came with, which didn’t run.":
    "Il a peut-être besoin des scripts d’installation fournis avec ses paquets, qui ne se sont pas lancés.",
  "It merged this part's work without a reviewer's verdict. The reviewers score parts that build in steps; this one was built in one session.":
    "Il a intégré le travail de cette partie sans l’avis d’un vérificateur. Les vérificateurs notent les parties créées par étapes ; celle-ci a été créée en une seule session.",
  "It merges into your build when the lead integrates this part.":
    "Ça rejoindra ton build quand l’agent principal intégrera cette partie.",
  "It needs macOS {version} or later.": "Il faut macOS {version} ou plus récent.",
  "It never uses password managers, Windows Settings, password prompts or Genex.":
    "Il n’utilise jamais les gestionnaires de mots de passe, les Paramètres Windows, les demandes de mot de passe ni Genex.",
  "It ran into an error": "Une erreur s’est produite",
  "It runs at Genex's moments: {steps}; those steps don't ask you first.":
    "Il s’exécute à certains moments de Genex : {steps} ; ces étapes ne te demandent rien avant.",
  "It runs with your access: Genex doesn't sandbox its code.":
    "Il s’exécute avec tes accès : Genex n’isole pas son code.",
  "It runs, but no reviewer compared it with the game you had.":
    "Ça tourne, mais aucun vérificateur ne l’a comparé au jeu que tu avais.",
  "It shows in the game after its next release.": "Il apparaît dans le jeu après sa prochaine sortie.",
  "It shows up here as soon as it runs.": "Il s’affichera ici dès qu’il tournera.",
  "It starts off: turn it on in Plugins; each of its tools asks you before it runs.":
    "Il démarre désactivé : active-le dans Plugins ; chacun de ses outils te demandera avant de s’exécuter.",
  "It stopped before this was fixed.": "Ça s’est arrêté avant que ce soit corrigé.",
  "It treats this as a {kind} game — that decides the controls it drives before every look, and who reviews it.":
    "Il le traite comme un jeu de type « {kind} » — cela décide des commandes qu’il utilise avant chaque coup d’œil, et de qui le vérifie.",
  "It turns on when installed: agents in all your games can use it from your next message.":
    "Il s’active dès l’installation : les agents de tous tes jeux peuvent l’utiliser dès ton prochain message.",
  "It was paused before it could write up the build.": "Il a été mis en pause avant de pouvoir résumer le build.",
  "It's no longer there.": "Ce n’est plus disponible.",
  "It's switched on in Studio's settings. Studio answers once a place is open: open one in Studio, or press New Roblox game.":
    "Il est activé dans les réglages de Studio. Studio répond dès qu’un lieu est ouvert : ouvres-en un dans Studio, ou appuie sur « Nouveau jeu Roblox ».",
  "It's switched on in Studio's settings. Studio answers once it has finished opening.":
    "Il est activé dans les réglages de Studio. Studio répond une fois complètement ouvert.",
  "Its author no longer shares it.": "Son auteur ne le partage plus.",
  "Its code runs on your computer like an app you install. It isn't sandboxed.":
    "Son code s’exécute sur ton ordinateur comme une app que tu installes. Il n’est pas dans un bac à sable.",
  "Its creator hasn’t shared this game’s project yet, so it can’t be remixed.":
    "Son créateur n’a pas encore partagé le projet de ce jeu, donc on ne peut pas le remixer.",
  "Its files are in your game folder, waiting for the lead to use them.":
    "Ses fichiers sont dans le dossier de ton jeu et attendent que l’agent principal les utilise.",
  "Its own scene": "Scène à part",
  "Its packages aren’t installed yet — “{install}” runs on one press.":
    "Ses paquets ne sont pas encore installés — « {install} » se lance en un clic.",
  "Its packages aren’t installed yet.": "Ses paquets ne sont pas encore installés.",
  "Its project didn’t go, so no one can remix it yet.":
    "Son projet n’est pas parti, donc personne ne peut encore le remixer.",
  "Its project is too big to remix: Genex keeps up to 5 GB and 5,000 files.":
    "Son projet est trop gros pour être remixé : Genex garde jusqu’à 5 Go et 5 000 fichiers.",
  "Its session failed before it delivered anything.": "Sa session a échoué avant de livrer quoi que ce soit.",
  "Its source is your own repository: run genex make-remixable in the game’s folder to allow remixing.":
    "Son code source est dans ton propre dépôt : lance genex make-remixable dans le dossier du jeu pour autoriser les remix.",
