    "Chargé depuis un dossier de ce Mac. Il s’exécute avec tes accès, et chacun de ses outils te demande avant qu’un agent l’utilise ; ses propres étapes aux moments de Genex ne demandent rien.",
  "Loaded from a folder on this Mac. It runs with your access: its code isn't sandboxed. Each of its tools asks you before an agent runs it; its own steps at Genex's moments don't ask.":
    "Chargé depuis un dossier de ce Mac. Il tourne avec tes droits : son code n’est pas isolé. Chacun de ses outils te demande avant qu’un agent l’utilise ; ses propres étapes aux moments clés de Genex ne demandent rien.",
