  "This project was saved with Unity {version}: Genex works with Unity 6 or later":
    "Ce projet a été enregistré avec Unity {version} : Genex fonctionne avec Unity 6 ou plus récent",
  "This project's Packages/manifest.json can't be read as Unity writes it. Fix the file, then set it up again.":
    "Le Packages/manifest.json de ce projet ne peut pas être lu comme Unity l’écrit. Corrige le fichier, puis configure le projet à nouveau.",
